import{_ as l,a0 as p,w as d,s as r,ao as o,I as n,x as a,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用 grubby 更改 RHEL 8 和 9 的默認內核 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 grubby 更改 RHEL 8 和 9 的默認內核 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 grubby 更改 RHEL 8 和 9 的默認內核 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 grubby 更改 RHEL 8 和 9 的默認內核 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230816 How to Change the default kernel in RHEL 8 and 9","title":"如何使用 grubby 更改 RHEL 8 和 9 的默認內核","tag":"202309","desc":""},"relativePath":"202309/20230816 How to Change the default kernel in RHEL 8 and 9.md","filePath":"[post].md"}'),h={name:"202309/20230816 How to Change the default kernel in RHEL 8 and 9.md"};function g(b,s,u,c,k,f){const e=p("Link");return d(),r("div",null,[s[15]||(s[15]=o(`<h1 id="如何使用-grubby-更改-rhel-8-和-9-的默認內核" tabindex="-1">如何使用 grubby 更改 RHEL 8 和 9 的默認內核 <a class="header-anchor" href="#如何使用-grubby-更改-rhel-8-和-9-的默認內核" aria-label="Permalink to “如何使用 grubby 更改 RHEL 8 和 9 的默認內核”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/01/105123phdy0f0fmgavquqq.jpg" alt=""></p><p>通常 Linux 系統會默認引導系統進入最新安裝的內核，並保留最新的 3 個 Linux 內核引導條目。</p><p>假設你已經執行了 <code>yum update</code>，並且新的內核作為更新的一部分已經安裝了。這時，由於這個新內核與應用程序不兼容，它會阻止應用程序啓動。</p><p>想要暫時解決這個問題，你應該還是引導系統進入舊內核。</p><p>在本文中，我們將向您展示如何使用 <code>grubby</code> 工具將舊的內核版本設置為 RHEL 8 和 RHEL 9 系統上的默認版本。</p><h3 id="grubby-是什麼" tabindex="-1">grubby 是什麼 <a class="header-anchor" href="#grubby-是什麼" aria-label="Permalink to “grubby 是什麼”">​</a></h3><p><code>grubby</code> 是一個命令列工具，用於在多個架構上更新和顯示引導加載配置文件的信息。</p><h3 id="檢查當前引導的內核" tabindex="-1">檢查當前引導的內核 <a class="header-anchor" href="#檢查當前引導的內核" aria-label="Permalink to “檢查當前引導的內核”">​</a></h3><p>你可以使用如下的 <code>uname</code> 命令來檢查當前引導/加載的內核。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># uname -r</span></span>
<span class="line"><span>4.18.0-477.13.1.el8_8.x86_64</span></span></code></pre></div><h3 id="列出默認內核" tabindex="-1">列出默認內核 <a class="header-anchor" href="#列出默認內核" aria-label="Permalink to “列出默認內核”">​</a></h3><p>使用 <code>grubby</code> 驗證默認內核版本，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --default-kernel</span></span>
<span class="line"><span>/boot/vmlinuz-4.18.0-477.13.1.el8_8.x86_64</span></span></code></pre></div><p>要獲取當前默認內核的索引號，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --default-index</span></span>
<span class="line"><span>0</span></span></code></pre></div><h3 id="檢查已安裝的內核" tabindex="-1">檢查已安裝的內核 <a class="header-anchor" href="#檢查已安裝的內核" aria-label="Permalink to “檢查已安裝的內核”">​</a></h3><p>要檢查已安裝的內核的列表，請運行以下命令：</p><p>我們來解釋以下的輸出信息。最新安裝的內核的<strong>條目索引</strong>為 <code>0</code>，接下來的 <strong>較舊的內核</strong> 版本將會是 <code>1</code>，第二個更舊的內核版本將會是 <code>2</code>，而 <strong>救援內核</strong> 的條目索引將會是 <code>3</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --info=ALL | egrep -i &#39;index|title&#39;</span></span>
<span class="line"><span>index=0</span></span>
<span class="line"><span>title=&quot;Red Hat Enterprise Linux (4.18.0-477.13.1.el8_8.x86_64) 8.8 (Ootpa)&quot;</span></span>
<span class="line"><span>index=1</span></span>
<span class="line"><span>title=&quot;Red Hat Enterprise Linux (4.18.0-425.19.2.el8_7.x86_64) 8.7 (Ootpa)&quot;</span></span>
<span class="line"><span>index=2</span></span>
<span class="line"><span>title=&quot;Red Hat Enterprise Linux (4.18.0-425.13.1.el8_7.x86_64) 8.7 (Ootpa)&quot;</span></span>
<span class="line"><span>index=3</span></span>
<span class="line"><span>title=&quot;Red Hat Enterprise Linux (0-rescue-13iu76884ec5490puc67j8789s249b0c) 8.2 (Ootpa)&quot;</span></span></code></pre></div><h3 id="更改默認內核引導條目" tabindex="-1">更改默認內核引導條目 <a class="header-anchor" href="#更改默認內核引導條目" aria-label="Permalink to “更改默認內核引導條目”">​</a></h3><p>我們可以用兩種方式，使用 “內核文件名”，或者使用 “內核條目索引”。我們設置索引號為 <code>1</code> 的 <code>4.18.0-425.19.2.el8_7.x86_64</code> 為默認內核，以此滿足應用程序的依賴關係。</p><p>語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default [kernel-filename]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default /boot/vmlinuz-4.18.0-425.19.2.el8_7.x86_64</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default vmlinuz-4.18.0-425.19.2.el8_7.x86_64</span></span></code></pre></div><p>使用內核條目索引更改默認的內核引導：</p><p>語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default-index=[kernel-entry-index]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --set-default-index=1</span></span></code></pre></div><h3 id="重啓系統" tabindex="-1">重啓系統 <a class="header-anchor" href="#重啓系統" aria-label="Permalink to “重啓系統”">​</a></h3><p>重啓系統，檢查舊內核是否持久更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># reboot</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># init 6</span></span></code></pre></div><h3 id="驗證更改" tabindex="-1">驗證更改 <a class="header-anchor" href="#驗證更改" aria-label="Permalink to “驗證更改”">​</a></h3><p>讓我們檢查一下在上一步中添加的內核是否生效了。好了，按我們的預期使用了較舊的內核 “N-1” 進行引導了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># uname -r</span></span>
<span class="line"><span>4.18.0-425.19.2.el8_7.x86_64</span></span>
<span class="line"><span># grubby --default-kernel</span></span>
<span class="line"><span>/boot/vmlinuz-4.18.0-425.19.2.el8_7.x86_64</span></span></code></pre></div><p>要檢查所有內核的詳細信息，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grubby --info=ALL</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2023/06/changing-default-kernel-rhel-8-rhel-9-1024x494.jpg" alt=""></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在本教程中，我們展示瞭如何使用 <code>grubby</code> 工具在 RHEL 8 和 RHEL 9 系統上將舊版本內核設置為默認。</p><p>如果有任何問題或反饋，歡迎在下方發表評論。</p><p><em>（題圖：MJ/9204b9c1-c1ad-4694-b2f6-a7d983976d22）</em></p><hr>`,47)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.2daygeek.com/changing-default-kernel-rhel-8-rhel-9/"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.2daygeek.com/changing-default-kernel-rhel-8-rhel-9/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=a("作者：",-1)),i(e,{href:"https://www.2daygeek.com/author/rasool/"},{default:t(()=>[...s[2]||(s[2]=[a("Rasool Cool",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(e,{href:"https://github.com/onionstalgia"},{default:t(()=>[...s[4]||(s[4]=[a("onionstalgia",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=l(h,[["render",g]]);export